}

In the following example, a custom template is defined for the .

<SfSpinner @bind-Visible="@SpinnerVisible">
  <SpinnerTemplates>
      <Template>
          <div class="custom-spinner-template">
              <div class="spinner-dot"></div>
              <span>Loading...</span>
          </div>
      </Template>
  </SpinnerTemplates>
</SfSpinner>

<style>
.custom-spinner-template {
    display: flex;
    align-items: center;
    justify-content: center;
    flex-direction: column;
}
.spinner-dot {
   width: 20px;
   height: 20px;
   border-radius: 50%;
   background-color: #007bff;
   animation: bounce 1.4s infinite ease-in-out both;
}
@keyframes bounce {
  0%, 80%, 100% { transform: scale(0); }
  40% { transform: scale(1.0); }
}
</style>

@code {
    private bool SpinnerVisible { get; set; } = true;
}

A simple Spinner component with Material theme.

@using Syncfusion.Blazor.Spinner

<SfSpinner Type="SpinnerType.Material"></SfSpinner>

The following example demonstrates how to use the  in an event handler to cancel the spinner's visibility change.

<SfSpinner @bind-Visible="@IsVisible" >
    <SpinnerEvents OnBeforeOpen="BeforeOpenHandler"></SpinnerEvents>
</SfSpinner>
@code {
    private bool IsVisible { get; set; } = true;
    private void BeforeOpenHandler(SpinnerEventArgs args)
    {
        // Cancels the spinner from being shown
        args.Cancel = true;
    }
}

A simple Spinner component.

<SfSpinner @bind-Visible="@SpinnerVisible" />

@code {
    private bool SpinnerVisible { get; set; } = true;
}

The following example demonstrates how to use the  and  methods.

<SfSpinner @ref="Spinner" />
<button @onclick="ProcessData">Process Data</button>
@code {
    private SfSpinner Spinner;
    private async Task ProcessData()
    {
        await Spinner.ShowAsync();
        // Simulate a long-running task
        await Task.Delay(2000);
        await Spinner.HideAsync();
    }
}

